using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly string[] _labels;

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        IConfiguration configuration)
    {
        _predictionPool = predictionPool;

        // Load label order from the trained model's key-value mapping
        var mlContext = new MLContext();
        var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        var model = mlContext.Model.Load(modelPath, out _);
        var transformer = model as ITransformer;
        var outputSchema = transformer!.GetOutputSchema(
            SchemaDefinition.Create(typeof(TicketInput)).ToDataViewSchema(mlContext));
        var labelColumn = outputSchema.GetColumnOrNull("PredictedLabel");
        if (labelColumn is null)
            throw new InvalidOperationException("Model missing PredictedLabel column");

        // Extract the key-value metadata to get the ordered labels
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        outputSchema["Score"].GetSlotNames(ref slotNames);
        _labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }

    [HttpPost("classify")]
    public ActionResult<TicketResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < _labels.Length && i < prediction.Score.Length; i++)
        {
            scores[_labels[i]] = prediction.Score[i];
        }

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.Category,
            Scores = scores
        });
    }
}

